function Villagegismap() {
    var map3 = null;
    var location = null;
    if ($("#selecteddistrict").val() == "s") {
        alert('Please select itda');

    }
    else {


        var hidField1 = "PADERU";

        var hidField2 = "KOYYURU";
        var hidField3 = "Koyyuru";
        var hidField4 = "";
        var hidField5 = "5";
        $.ajax(
       {
           type: 'POST',
           contentType: 'application/json; charset=utf-8',
           url: '/api/ITDA/ItdaLatlongslist',
           data: "{'ITDA':'" + hidField1 + "', 'MANDAL':'" + hidField2 + "', 'VILLAGE':'" + hidField3 + "', 'Category':'" + hidField4 + "', 'Type':'" + hidField5 + "'}",
           dataType: "json",
           success: function (response) {
               console.log(JSON.stringify(response));
               var dist = response;
               var LAT = '17.998426';
               var LONG = '82.739254';
               location = new google.maps.LatLng(LAT, LONG);
               map3 = new google.maps.Map(document.getElementById('map1'), {
                   zoom: 10,
                   center: location,
                   mapTypeId: google.maps.MapTypeId.HYBRID
               });
               var bounds = new google.maps.LatLngBounds();
               arr = [];
               for (var i = 0; i < dist.itdalist.length; i++) {

                   arr.push(new google.maps.LatLng(
                           parseFloat(dist.itdalist[i].LATTITUDE),
                         parseFloat(dist.itdalist[i].LONGITUDE)
                    ));
                   bounds.extend(arr[arr.length - 1])


               }

               if (dist.itdalist.length >= 3000) {

                   polygons.push(new google.maps.Polygon({
                       paths: arr,
                       strokeColor: '#FF0000',
                       strokeOpacity: 0.8,
                       strokeWeight: 3,
                       fillColor: '',
                       fillOpacity: 0
                   }));
                   polygons[polygons.length - 1].setMap(map3);
                   map3.fitBounds(bounds);
               }
               else {
                   polygons.push(new google.maps.Polygon({
                       paths: arr,
                       strokeColor: '#FF0000',
                       strokeOpacity: 0.8,
                       strokeWeight: 3,
                       fillColor: '',
                       fillOpacity: 0
                   }));
                   polygons[polygons.length - 1].setMap(map3);
                   map3.fitBounds(bounds);
               }



           },
           error: function (result) {
               alert("Error");
           }

       });
    }


}
